<?php
require_once __DIR__ . '/includes/company_helpers.php';
if(is_post()){
 require_csrf();$id=(int)input('id');$employee=company_optional_id('employee_id');$project=company_optional_id('project_id');$month=trim((string)input('period_month'));
 $monthDate=preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$month)?$month.'-01':false;
 $base=company_decimal('base_salary');$allowances=company_decimal('allowances');$deductions=company_decimal('deductions');$contrib=company_decimal('employer_contributions');
 $status=company_enum(input('payment_status'),['pending','paid'],'pending');$paidDate=company_valid_date(company_input('payment_date',10));$notes=company_input('notes',5000);
 $employeeRow=$employee?db_fetch('SELECT id FROM company_employees WHERE id=?',[$employee]):null;
 $projectRow=$project?db_fetch('SELECT id FROM company_projects WHERE id=?',[$project]):null;
 if(!$employeeRow||($project&&!$projectRow)||!$monthDate||$base===false||$allowances===false||$deductions===false||$contrib===false||$base+$allowances<$deductions||$paidDate===false||($status==='paid'&&!$paidDate)){
  company_flash_error('راجع الموظف والشهر ومكونات الراتب. تاريخ الصرف مطلوب إذا كانت الحالة «تم الصرف»، والخصومات لا تتجاوز إجمالي المستحق.');
 }else{
  $net=round($base+$allowances-$deductions,2);
  try{
   if($id>0){db_query('UPDATE company_payroll SET employee_id=?,project_id=?,period_month=?,base_salary=?,allowances=?,deductions=?,employer_contributions=?,net_pay=?,payment_status=?,payment_date=?,notes=? WHERE id=?',[$employee,$project,$monthDate,$base,$allowances,$deductions,$contrib,$net,$status,$paidDate,$notes?:null,$id]);company_activity('تعديل كشف راتب','الموظف رقم '.$employee.' / '.$month);flash('success','تم تحديث كشف الراتب.');}
   else{db_query('INSERT INTO company_payroll (employee_id,project_id,period_month,base_salary,allowances,deductions,employer_contributions,net_pay,payment_status,payment_date,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$employee,$project,$monthDate,$base,$allowances,$deductions,$contrib,$net,$status,$paidDate,$notes?:null]);company_activity('إضافة كشف راتب','الموظف رقم '.$employee.' / '.$month);flash('success','تم تسجيل كشف الراتب.');}
   redirect('payroll.php');
  }catch(PDOException $ex){company_flash_error('يوجد كشف راتب مسجل بالفعل لهذا الموظف وهذا الشهر، أو تعذر حفظ البيانات.');}
 }
}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$payroll=$editId?db_fetch('SELECT * FROM company_payroll WHERE id=?',[$editId]):null;
$employees=db_fetch_all('SELECT id,full_name,job_title,base_salary,employment_status FROM company_employees ORDER BY FIELD(employment_status,\'active\',\'leave\',\'inactive\'),full_name');
$projects=db_fetch_all('SELECT id,name FROM company_projects ORDER BY name');
$rows=db_fetch_all('SELECT p.*,e.full_name,e.job_title,cp.name project_name FROM company_payroll p JOIN company_employees e ON e.id=p.employee_id LEFT JOIN company_projects cp ON cp.id=p.project_id ORDER BY p.period_month DESC,p.payment_status,p.id DESC LIMIT 300');
$adminTitle='المرتبات';$adminSubtitle='كشوف المرتبات الشهرية للفريق';$adminActive='payroll';require __DIR__.'/includes/header.php';
?>
