<form method="post" action="payroll.php<?php echo $payroll?'?edit='.(int)$payroll['id']:''; ?>" data-loading><?php echo csrf_field(); ?><input type="hidden" name="id" value="<?php echo (int)($payroll['id']??0); ?>"><div class="panel"><div class="panel-head"><h2><?php echo $payroll?'تعديل كشف راتب':'كشف راتب شهري'; ?></h2></div><div class="panel-body"><div class="form-grid">
<div class="form-group"><label>الموظف *</label><select class="form-control" id="payrollEmployee" name="employee_id" required><option value="">اختر موظفًا</option><?php foreach($employees as $emp): ?><option data-salary="<?php echo e($emp['base_salary']); ?>" value="<?php echo (int)$emp['id']; ?>" <?php echo (int)($payroll['employee_id']??0)===(int)$emp['id']?'selected':''; ?>><?php echo e($emp['full_name'].' — '.$emp['job_title'].' ('.company_money($emp['base_salary']).')'); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>المشروع المرتبط بتكلفة العمل (اختياري)</label><select class="form-control" name="project_id"><option value="">تكلفة عامة على الشركة</option><?php foreach($projects as $pr): ?><option value="<?php echo (int)$pr['id']; ?>" <?php echo (int)($payroll['project_id']??0)===(int)$pr['id']?'selected':''; ?>><?php echo e($pr['name']); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>الشهر *</label><input class="form-control ltr" type="month" name="period_month" required value="<?php echo e(isset($payroll['period_month'])?substr($payroll['period_month'],0,7):date('Y-m')); ?>"></div>
<div class="form-group"><label>الراتب الأساسي (ج.م)</label><input class="form-control ltr" type="number" min="0" step="0.01" name="base_salary" required value="<?php echo e($payroll['base_salary']??'0'); ?>"></div><div class="form-group"><label>البدلات والمكافآت</label><input class="form-control ltr" type="number" min="0" step="0.01" name="allowances" value="<?php echo e($payroll['allowances']??'0'); ?>"></div>
<div class="form-group"><label>الخصومات</label><input class="form-control ltr" type="number" min="0" step="0.01" name="deductions" value="<?php echo e($payroll['deductions']??'0'); ?>"></div><div class="form-group"><label>مساهمات صاحب العمل</label><input class="form-control ltr" type="number" min="0" step="0.01" name="employer_contributions" value="<?php echo e($payroll['employer_contributions']??'0'); ?>"></div>
<div class="form-group"><label>حالة الصرف</label><select class="form-control" name="payment_status"><option value="pending" <?php echo ($payroll['payment_status']??'pending')==='pending'?'selected':''; ?>>معلق</option><option value="paid" <?php echo ($payroll['payment_status']??'')==='paid'?'selected':''; ?>>تم الصرف</option></select></div><div class="form-group"><label>تاريخ الصرف</label><input class="form-control ltr" type="date" name="payment_date" value="<?php echo e($payroll['payment_date']??''); ?>"></div>
<div class="form-group full"><label>ملاحظات</label><textarea class="form-control" name="notes" rows="2" maxlength="5000"><?php echo e($payroll['notes']??''); ?></textarea></div></div><p class="hint">صافي الموظف = الأساسي + البدلات − الخصومات. تكلفة المرتبات في تقرير الأرباح تضم الأساسي والبدلات ومساهمات الشركة.</p></div><div class="form-actions"><a class="btn btn-outline" href="payroll.php">إلغاء</a><div class="right"><button class="btn btn-primary" type="submit">حفظ كشف الراتب</button></div></div></div></form>
<div class="panel"><div class="panel-head"><h2>كشوف المرتبات (آخر 300)</h2></div><div class="panel-body p0"><div class="table-wrap"><table class="table"><thead><tr><th>الموظف والشهر</th><th>الأساسي</th><th>بدلات / خصومات</th><th>صافي الموظف</th><th>تكلفة الشركة</th><th>الصرف</th><th></th></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td><div class="cell-title"><?php echo e($row['full_name']); ?></div><div class="cell-sub"><?php echo e($row['job_title'].' · '.date('m/Y',strtotime($row['period_month']))); ?></div></td><td><?php echo e(company_money($row['base_salary'])); ?></td><td><?php echo e(company_money($row['allowances'])); ?><div class="cell-sub">خصم: <?php echo e(company_money($row['deductions'])); ?></div></td><td><?php echo e(company_money($row['net_pay'])); ?></td><td><?php echo e(company_money($row['base_salary']+$row['allowances']+$row['employer_contributions'])); ?><div class="cell-sub"><?php echo e($row['project_name']?:'تكلفة عامة'); ?></div></td><td><?php echo $row['payment_status']==='paid'?'مصروف':'معلق'; ?><div class="cell-sub"><?php echo e($row['payment_date']?:''); ?></div></td><td><a class="btn btn-outline btn-sm" href="payroll.php?edit=<?php echo (int)$row['id']; ?>">تعديل</a></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="7" class="muted">لا توجد كشوف مرتبات مسجلة.</td></tr><?php endif; ?></tbody></table></div></div></div>
